import copy
from datetime import timedelta
from io import StringIO

from django.core.management import call_command
from django.core.management.base import CommandError

from django.test import TestCase

from feedback_plugin.tests.utils import create_test_database
from feedback_plugin.models import Upload, Chart, ChartMetadata


class ComputeChartsCommand(TestCase):
    @staticmethod
    def call(*args, **kwargs):
        out = StringIO()
        err = StringIO()

        value = call_command(
            'compute_charts',
            *args,
            stdout=out,
            stderr=err,
            **kwargs
        )

        return (value, out, err)

    def test_call_command_no_parameters(self):
        self.assertRaisesMessage(CommandError,
                                 'No uploads, can not compute charts!',
                                 ComputeChartsCommand.call)
        create_test_database()

        ComputeChartsCommand.call('--recreate')

        first_upload = Upload.objects.all().order_by('upload_time')[:1][0]
        last_upload = Upload.objects.all().order_by('-upload_time')[:1][0]

        self.assertEqual(Chart.objects.all().count(), 4)
        self.assertEqual(ChartMetadata.objects.all().count(), 4)

        chart = Chart.objects.get(id='server-count')
        self.assertEqual(chart.title, 'Server Count by Month')
        self.assertEqual(chart.values,
                         {
                             'count': {
                                 'x': ['2022-01', '2022-02', '2022-03'],
                                 'y': [3, 4, 1],
                             }
                         })
        self.assertEqual(chart.metadata.computed_start_date,
                         first_upload.upload_time)
        self.assertEqual(chart.metadata.computed_end_date,
                         last_upload.upload_time)

        new_last_upload = copy.deepcopy(last_upload)
        new_last_upload.upload_time = last_upload.upload_time + timedelta(days=35)
        new_last_upload.id = None
        new_last_upload.save()

        new_first_upload = copy.deepcopy(first_upload)
        new_first_upload.upload_time = first_upload.upload_time - timedelta(days=20)
        new_first_upload.id = None
        new_first_upload.save()

        for _ in range(2):
            # Without recreate parameter, the chart only looks at follow-up data.
            # The second iteration ensures idempotency when no more new data is
            # available.
            ComputeChartsCommand.call()

            chart.refresh_from_db()
            self.assertEqual(chart.title, 'Server Count by Month')
            self.assertEqual(chart.values,
                             {
                                 'count': {
                                     'x': ['2022-01', '2022-02', '2022-03', '2022-04'],
                                     'y': [3, 4, 1, 1],
                                 }
                             })
            self.assertEqual(chart.metadata.computed_start_date,
                             first_upload.upload_time)
            self.assertEqual(chart.metadata.computed_end_date,
                             new_last_upload.upload_time)

        # With recreate parameter, the chart is recreated.
        ComputeChartsCommand.call('--recreate')

        chart.refresh_from_db()
        self.assertEqual(chart.title, 'Server Count by Month')
        self.assertEqual(chart.values,
                         {
                             'count': {
                                 'x': ['2021-12', '2022-01', '2022-02', '2022-03', '2022-04'],
                                 'y': [1, 3, 4, 1, 1],
                             }
                         })
        self.assertEqual(chart.metadata.computed_start_date,
                         new_first_upload.upload_time)
        self.assertEqual(chart.metadata.computed_end_date,
                         new_last_upload.upload_time)

    def test_compute_version_breakdown_by_month(self):
        create_test_database()

        ComputeChartsCommand.call('--recreate', '--chart=version-breakdown')

        self.assertEqual(Chart.objects.all().count(), 1)

        chart = Chart.objects.get(id='version-breakdown')

        self.assertEqual(chart.title, 'Server Version Breakdown by Month')
        self.assertEqual(chart.values,
                         {
                             '10.1': {
                                 'x': ['2022-2'],
                                 'y': [1]
                             },
                             '10.3': {
                                 'x': ['2022-1', '2022-2', '2022-3'],
                                 'y': [1, 1, 1]
                             },
                             '10.4': {
                                 'x': ['2022-1', '2022-2'],
                                 'y': [2, 2]
                             },
                         })

    def test_compute_architecture_breakdown_by_month(self):
        create_test_database()

        ComputeChartsCommand.call('--recreate', '--chart=architecture-breakdown')

        self.assertEqual(Chart.objects.all().count(), 1)

        chart = Chart.objects.get(id='architecture-breakdown')

        self.assertEqual(chart.title, 'Architecture Breakdown by Month')
        self.assertEqual(chart.values,
                         {
                            'x86_64': {
                                'x': ['2022-1', '2022-2', '2022-3'],
                                'y': [3, 4, 1],
                            }
                         })

    def test_compute_features_by_month(self):
        create_test_database()

        ComputeChartsCommand.call('--recreate', '--chart=feature-count')

        self.assertEqual(Chart.objects.all().count(), 1)

        chart = Chart.objects.get(id='feature-count')

        self.assertEqual(chart.title, 'Feature Count by Month')
        self.assertEqual(chart.values,
                         {
                            'check_constraint': {
                                'x': ['2022-01', '2022-02'],
                                'y': [2, 2],
                            },
                            'json': {
                                'x': ['2022-01', '2022-02'],
                                'y': [2, 2],
                            },
                            'subquery': {
                                'x': ['2022-01', '2022-02', '2022-03'],
                                'y': [2, 2, 1],
                            },
                            'timezone': {
                                'x': ['2022-01', '2022-02', '2022-03'],
                                'y': [2, 2, 1],
                            },
                         })

import random
from datetime import datetime, timedelta, timezone

from django.test import TestCase

from feedback_plugin.data_processing.charts import compute_server_count_by_month
from feedback_plugin.models import Server, Upload

class ComputeServerCount(TestCase):
  def test_basic(self):
    TOTAL_SERVERS = 9
    SERVERS_PER_MONTH = [4, 3, 2, 1]
    UPLOADS_PER_MONTH_PER_SERVER = 5

    times = []
    base_time = datetime(year=2022, month=2, day=15, tzinfo=timezone.utc)
    for i in range(len(SERVERS_PER_MONTH)):
      times.append(base_time - timedelta(days=31 * i))

    servers = []
    for i in range(TOTAL_SERVERS):
      s = Server()
      servers.append(s)
      s.save()

    uploads = []
    for i in range(len(SERVERS_PER_MONTH)):
      picked_servers = random.sample(servers, k=SERVERS_PER_MONTH[i])
      for server in picked_servers:
        for j in range(UPLOADS_PER_MONTH_PER_SERVER):
          u = Upload(
                upload_time=times[i] + timedelta(days=random.randint(1, 5)),
                server=server)
          u.save()

    # Test with a time interval over the random value introduced above.
    self.assertEqual(compute_server_count_by_month(times[-1],
                                                   times[0] + timedelta(days=6),
                                                   True),
                     {
                         'count': {
                             'x': ['2021-11', '2021-12', '2022-01', '2022-02'],
                             'y': [1, 2, 3, 4],
                         },
                     })

    self.assertEqual(compute_server_count_by_month(times[-2],
                                                   times[0] + timedelta(days=6),
                                                   True),
                     {
                         'count': {
                             'x': ['2021-12', '2022-01', '2022-02'],
                             'y': [2, 3, 4],
                         },
                     })
    self.assertEqual(compute_server_count_by_month(times[-2],
                                                   times[1] + timedelta(days=6),
                                                   True),
                     {
                         'count': {
                             'x': ['2021-12', '2022-01'],
                             'y': [2, 3],
                         },
                     })

    s_edge = Server()
    s_edge.save()

    first_upload_time = datetime(year=2022, month=5, day=2, hour=10,
                                 minute=10, tzinfo=timezone.utc)
    second_upload_time = datetime(year=2022, month=6, day=2, hour=10,
                                 minute=10, tzinfo=timezone.utc)
    Upload(upload_time=first_upload_time, server=s_edge).save()
    Upload(upload_time=second_upload_time, server=s_edge).save()


    self.assertEqual(compute_server_count_by_month(first_upload_time,
                                                   second_upload_time, False),
                     {
                         'count': {
                             'x': ['2022-06'],
                             'y': [1],
                         },
                     })

    self.assertEqual(compute_server_count_by_month(first_upload_time,
                                                   second_upload_time, True),
                     {
                         'count': {
                             'x': ['2022-05', '2022-06'],
                             'y': [1, 1],
                         },
                     })
